    if not urlparse(output_dir.url).scheme == 's3':
        raise ValueError("The provided directory is not an S3 bucket.")

    # Import boto3 and create an S3 client
    s3 = boto3.client('s3')

    # Try to get the "index.json" object using the `head_object` method
    try:
        s3.head_object(Bucket=output_dir.url.split('//')[-1], Key='index.json')
        raise ValueError("The directory already contains an 'index.json' file.")
    except botocore.exceptions.ClientError as e:
        if e.response['Error']['Code'] == "404":
            # The file does not exist, so we can proceed with deleting objects
            pass
        else:
            raise

    # Delete all objects within the specified prefix in the bucket
    response = s3.list_objects_v2(Bucket=output_dir.url.split('//')[-1], Prefix='')
    while True:
        for obj in response['Contents']:
            s3.delete_object(Bucket=output_dir.url.split('//')[-1], Key=obj['Key'])
        try:
            response = s3.list_objects_v2(Bucket=output_dir.url.split('//')[-1], Prefix='', ContinuationToken=response['NextContinuationToken'])
        except botocore.exceptions.ClientError as e:
            if e.response['Error']['Code'] == "404":
                break
            else:
                raise
